public OrderResult create(OrderRequest req) {
    // 1. 参数校验
    if (req.getProductId() == null) {
        throw new IllegalArgumentException("productId required");
    }
    // 2. 库存校验
    int stock = inventoryService.getStock(req.getProductId());
    if (stock < req.getQuantity()) {
        throw new InsufficientStockException(req.getProductId());
    }
    // 3. 创建订单
    Order order = new Order();
    order.setProductId(req.getProductId());
    order.setQuantity(req.getQuantity());
    order.setStatus(OrderStatus.CREATED);
    try {
        orderRepo.save(order);
    } catch (DataAccessException e) {
        log.error("DB save failed", e);
        throw new OrderPersistException("订单持久化失败", e);
    }
    // 4. 发送消息
    kafkaTemplate.send("order-created", order.getId().toString());
    return OrderResult.success(order);
}
